export type AgentTurnTrigger = "user" | "delegation" | "recovery";

export type AgentTurnStatus = "queued" | "active" | "completed" | "failed" | "cancelled";

export type AgentRunStatus = "queued" | "running" | "waiting" | "pausing" | "paused" | "cancelling" | "cancelled" | "completed" | "failed" | "interrupted" | "recovery_required";

export type AgentWaitingReason = "user" | "approval" | "child" | "external" | "backoff" | "budget" | "reconcile";

export type AgentExecutionKind = "model_call" | "tool_call" | "wait" | "delegation" | "verification";

export type AgentExecutionStatus = "prepared" | "awaiting_user" | "dispatching" | "running" | "succeeded" | "failed" | "rejected" | "cancelled" | "outcome_unknown";

export type AgentDeliveryMode = "followup" | "steer" | "inject";

export type AgentExecutionMode = "autonomous" | "review_writes" | "advice_only";

export type AgentControlAction = "pause" | "resume" | "cancel";

export type AgentInboxKind = "followup" | "steer" | "inject" | "control" | "child_result";

export type AgentInboxStatus = "pending" | "claimed" | "consumed" | "superseded" | "cancelled";

export type AgentDelegationStatus = "pending" | "running" | "awaiting_acceptance" | "revision_requested" | "accepted" | "failed" | "cancelled" | "interrupted";

export type AgentApprovalStatus = "pending" | "approved" | "rejected" | "expired" | "consumed";

export type AgentApprovalDecision = "approve" | "reject";

export type AgentMemoryScopeKind = "user" | "project" | "thread";

export type AgentMemoryStatus = "proposed" | "active" | "superseded" | "retracted";

export type AgentToolExposure = "hidden" | "discoverable" | "preloaded";

export type AgentToolRisk = "low" | "medium" | "high" | "critical";

export type AgentToolReversibility = "reversible" | "compensatable" | "irreversible" | "unknown";

export type AgentToolReplayPolicy = "safe" | "idempotent" | "reconcile_required" | "never";

export type AgentToolCostClass = "none" | "llm" | "image" | "video" | "external_unknown";

